const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const needles = ee.Geometry.Point([-114.6186, 34.8486]); // Needles, California coordinates
  const startDate = '2017-06-15';
  const endDate = '2017-06-22'; // Exclusive end date for ee.Filter.date

  // 2. Data Acquisition & Check
  const era5Collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(needles)
    .select('temperature_2m'); // Select 2m air temperature band (in Kelvin)

  const collectionSize = await era5Collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No ERA5-Land data found for the specified date range and location.");
    console.log("C1");
    return;
  }
  console.log(`ERA5-Land images found: ${collectionSize}`);

  // 3. Processing
  // Convert Kelvin to Fahrenheit for each image
  const fahrenheitCollection = era5Collection.map(image => {
    const kelvin = image.select('temperature_2m');
    const celsius = kelvin.subtract(273.15); // K to C
    const fahrenheit = celsius.multiply(9 / 5).add(32); // C to F
    return image.addBands(fahrenheit.rename('temperature_fahrenheit'));
  }).select('temperature_fahrenheit'); // Keep only the Fahrenheit band

  // Calculate the maximum temperature over the entire period
  const maxTempImage = fahrenheitCollection.max();

  // Reduce the maximum temperature image to get the value at the point
  // Use a reasonable scale like 1000 for point extraction to avoid memory issues for global datasets
  const maxTempStats = await maxTempImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: needles,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const maxTempFahrenheit = maxTempStats ? maxTempStats['temperature_fahrenheit'] : null;

  // 4. Validation & Final Answer
  if (maxTempFahrenheit === null || isNaN(maxTempFahrenheit)) {
    console.log("Calculation of maximum temperature failed or resulted in an invalid value.");
    console.log("C3");
    return;
  }

  // To check for C2 (no valid pixels): For ERA5-Land at a single point, if maxTempFahrenheit is valid,
  // it implies valid pixels. A direct pixel count for a single point is less relevant here.
  // The 'null' check above covers the practical aspect of C2 for point data in this context.

  const threshold = 115;
  const didReachThreshold = maxTempFahrenheit >= threshold;

  console.log(`Maximum temperature in Needles, CA between ${startDate} and ${endDate}: ${maxTempFahrenheit.toFixed(2)} °F`);

  if (didReachThreshold) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
